import (
	"context"
	"fmt"
	"time"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state with restricted options
	L := lua.NewState(lua.Options{
		SkipOpenLibs: true, // Don't open any libraries by default
	})
	defer L.Close()

	// Only open safe libraries - explicitly exclude os, io, debug, loadfile, dofile
	openSafeLibraries(L)

	// Set execution timeout to prevent infinite loops
	execCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	L.SetContext(execCtx)

	// Load and execute the script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the calculate_final_price function from global scope
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function or not defined")
	}

	// Convert Go context map to Lua table
	ctxTable := L.NewTable()
	for k, v := range ctx {
		L.SetField(ctxTable, k, lua.LNumber(v))
	}

	// Call the function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Get the result from the Lua stack
	result := L.Get(-1)
	L.Pop(1) // Remove the result from the stack

	// Convert result to float64
	if result.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price did not return a number")
	}

	return float64(result.(lua.LNumber)), nil
}

// openSafeLibraries opens only the safe Lua libraries needed for pricing calculations
func openSafeLibraries(L *lua.LState) {
	// Open base library but remove dangerous functions
	lua.OpenBase(L)

	// Remove dangerous base functions
	L.SetGlobal("dofile", lua.LNil)
	L.SetGlobal("loadfile", lua.LNil)
	L.SetGlobal("load", lua.LNil)
	L.SetGlobal("loadstring", lua.LNil)
	L.SetGlobal("require", lua.LNil)
	L.SetGlobal("module", lua.LNil)
	L.SetGlobal("collectgarbage", lua.LNil)
	L.SetGlobal("rawget", lua.LNil)
	L.SetGlobal("rawset", lua.LNil)
	L.SetGlobal("rawequal", lua.LNil)
	L.SetGlobal("getmetatable", lua.LNil)
	L.SetGlobal("setmetatable", lua.LNil)
	L.SetGlobal("getfenv", lua.LNil)
	L.SetGlobal("setfenv", lua.LNil)

	// Open math library - safe and needed for pricing calculations
	lua.OpenMath(L)

	// Open string library - generally safe for string manipulation
	lua.OpenString(L)

	// Open table library - safe for table operations
	lua.OpenTable(L)

	// Explicitly DO NOT open:
	// - lua.OpenOs (file system access, command execution)
	// - lua.OpenIo (file I/O)
	// - lua.OpenDebug (can break sandbox)
	// - lua.OpenPackage (can load external modules)
	// - lua.OpenChannel (gopher-lua specific, could cause issues)
	// - lua.OpenCoroutine (could be used for resource exhaustion)
}

func main() {
	// Example usage
	script := `
	function calculate_final_price(ctx)
		-- Apply 10% discount for VIP users (tier 2)
		if ctx.user_tier >= 2 then
			return ctx.base_price * 0.9
		else
			return ctx.base_price
		end
	end
	`

	ctx := map[string]float64{
		"base_price": 100.0,
		"user_tier":  2.0,
	}

	result, err := ExecutePricingScript(script, ctx)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Final price: %.2f\n", result)
}

