	lua.OpenTable(L)  // Table manipulation
	lua.OpenString(L) // String manipulation
	lua.OpenMath(L)   // Math operations - essential for pricing calculations

	// Explicitly NOT opening:
	// - lua.OpenOs: file system and command execution
	// - lua.OpenIo: file I/O operations
	// - lua.OpenDebug: can be used to break sandboxing
	// - lua.OpenPackage: can load external modules
	// - lua.OpenChannel: gopher-lua specific, could cause issues
	// - lua.OpenCoroutine: could be used for resource exhaustion
}

func main() {
	// Example usage
