// ExecutePricingScript executes a user-provided Lua script to calculate the final price.
// The script must define a global function named `calculate_final_price` that takes a context table
// and returns a number representing the final price.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state
	L := lua.NewState()
	defer L.Close()

	// Execute the Lua script to define the calculate_final_price function
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the calculate_final_price function from global scope
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, errors.New("calculate_final_price function not found in script")
	}

	// Convert the Go map to a Lua table
	ctxTable := L.NewTable()
	for key, value := range ctx {
		L.SetField(ctxTable, key, lua.LNumber(value))
	}

	// Call the calculate_final_price function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Get the return value from the stack
	ret := L.Get(-1)
	L.Pop(1)

	// Verify the return type is a number
	if ret.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price must return a number, got %s", ret.Type().String())
	}

	// Convert to float64 and return
	result := float64(ret.(lua.LNumber))
	return result, nil
}

